                    "number of decode upstream server %ui and group %ui not equal", peers->number, olcf->decode_groups->nelts);
                return NGX_ERROR;
            }
        } else {
            ngx_http_upstream_rr_peers_unlock(peers);
            continue;
        }
        ngx_http_upstream_rr_peers_unlock(peers);
    }

    return NGX_OK;
}

